// Number handling with arbitrary precision
use serde_json::{Number, Value};

#[derive(Debug, Clone)]
pub struct ParsedNumber {
    pub sign: i8, // 1 or -1 (0 is positive)
    pub digits: String, // significant digits without leading zeros, without decimal point; "0" for zero
    pub exponent: i32, // value = digits * 10^exponent? Actually digits as integer *10^exponent
    pub is_zero: bool,
