pub fn parse_number_str(s: &str) -> ParsedNumber {
    // s is normalized number string from serde_json Number::to_string() with arbitrary_precision
    // e.g., "1.00", "1e+3", "-0.0", "0", "100000...", "1.5e+2"
    let s = s.trim();
    let mut sign: i8 = 1;
    let mut rest = s;
    if rest.starts_with('-') {
        sign = -1;
        rest = &rest[1..];
    } else if rest.starts_with('+') {
        rest = &rest[1..];
    }
    // Split exponent
    let (mantissa, exp_part) = if let Some(pos) = rest.find(|c| c == 'e' || c == 'E') {
        let (m, e) = rest.split_at(pos);
        let e_str = &e[1..]; // skip e
        // e_str may be "+03", "-03", "3"
        let exp: i32 = e_str.parse().unwrap_or(0);
        (m, exp)
    } else {
        (rest, 0)
    };
    // mantissa may contain '.'
    let (int_part, frac_part) = if let Some(dot) = mantissa.find('.') {
        let (i, f) = mantissa.split_at(dot);
        (i, &f[1..])
    } else {
        (mantissa, "")
    };
    // Combine digits: int_part + frac_part
    let mut digits = format!("{}{}", int_part, frac_part);
    // Remove leading zeros
    // Keep at least one digit
    let mut exp_adjust = exp_part - (frac_part.len() as i32);
    // Remove leading zeros from digits
    let trimmed = digits.trim_start_matches('0');
    if trimmed.is_empty() {
        // zero
        return ParsedNumber { sign: 1, digits: "0".to_string(), exponent: 0, is_zero: true };
    } else {
        digits = trimmed.to_string();
        // Remove trailing zeros? For comparison, keep them? Actually for value, trailing zeros don't matter, but for exponent they do.
        // We keep digits as is (with trailing zeros), exponent as is. For comparison, we handle trailing zeros via length?
        // Alternatively, strip trailing zeros and adjust exponent? Let's strip to normalize for comparison.
        // Example: "1.00" => int="1", frac="00", digits="100", exp=-2. Strip trailing zeros: digits="1", exp=0? Since 100*10^-2 =1*10^0. Good.
        // Example: "10" => digits="10", exp=0. Strip trailing zero: digits="1", exp=1. Since 10*10^0=1*10^1. Good.
        // This normalization makes comparison easier (no trailing zeros).
        while digits.ends_with('0') && digits.len() > 1 {
            digits.pop();
            exp_adjust += 1;
