        return ParsedNumber { sign, digits, exponent: exp_adjust, is_zero: false };
    }
}

pub fn parse_value_number(n: &Number) -> ParsedNumber {
    let s = n.to_string();
    parse_number_str(&s)
}

pub fn compare_numbers(a: &Number, b: &Number) -> std::cmp::Ordering {
    let pa = parse_value_number(a);
    let pb = parse_value_number(b);
    compare_parsed(&pa, &pb)
}

pub fn compare_parsed(a: &ParsedNumber, b: &ParsedNumber) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    if a.is_zero && b.is_zero {
        return Ordering::Equal;
    }
    if a.is_zero {
        // a==0, b!=0
        if b.sign > 0 { return Ordering::Less; } else { return Ordering::Greater; }
    }
    if b.is_zero {
        if a.sign > 0 { return Ordering::Greater; } else { return Ordering::Less; }
    }
    if a.sign != b.sign {
        if a.sign < b.sign { return Ordering::Less; } else { return Ordering::Greater; }
    }
    // same sign, compare magnitude
    let ord = compare_magnitude(a, b);
    if a.sign > 0 { ord } else { ord.reverse() }
