        // Check for leading/trailing dot or double dot?
        if spec.starts_with('.') || spec.ends_with('.') || spec.contains("..") {
            return false;
        }
        // Split by dot, each part must be non-empty and contain only ALPHA/DIGIT/_/pct-encoded
        for part in spec.split('.') {
            if part.is_empty() { return false; }
            // Check pct-encoded: % must be followed by 2 hex
            let bytes = part.as_bytes();
            let mut j = 0;
            while j < bytes.len() {
