// Helper to escape JSON pointer token
pub fn escape_pointer(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}
pub fn unescape_pointer(s: &str) -> String {
    // Must replace ~1 first? Actually ~01? Standard: ~1 -> /, ~0 -> ~. Order matters: replace ~1 first? No, replace ~0 last? Actually to unescape, replace ~1 -> /, then ~0 -> ~? Or vice versa? Standard says transform ~1 to / then ~0 to ~? Let's do ~1 first? For "~01": Should be "~1"? Hmm. Correct order: Replace ~1 with /, then ~0 with ~? For "~01": First ~1? No ~1 substring? "~01" contains "~0" at 0, "~1" overlapping? Actually "~01" is chars '~','0','1'. If we replace ~1 first, we look for "~1" substring: positions 1-2 are "01", not "~1", so no replace. Then replace ~0: "~0" at 0-1 => "~", leaving "1" => "~1". Good. If we did ~0 first, same. For "~10": chars '~','1','0'. Replace ~1 first: "~1" at 0-1 => "/", leaving "0" => "/0". Then ~0: no "~0" (since "/0" has no ~), so "/0". Good. If we did ~0 first: "~10" has no "~0" (since "~1" at 0-1, "10" at 1-2), so no change, then ~1 => "/0". Same. So order doesn't matter much? Standard says evaluate ~1 then ~0? We'll do ~1 then ~0.
    s.replace("~1", "/").replace("~0", "~")
}

pub fn json_pointer_get<'a>(value: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() { return Some(value); }
    if !pointer.starts_with('/') { return None; }
    let mut cur = value;
    for token in pointer[1..].split('/') {
        let token = unescape_pointer(token);
        match cur {
            Value::Object(map) => {
                cur = map.get(&token)?;
            }
            Value::Array(arr) => {
                // token must be index (no leading zeros? "01" invalid? JSON pointer for arrays: index must be 0 or [1-9][0-9]*, no leading zeros, and "-" is invalid for retrieval? For our purposes, parse as usize, reject leading zeros and "-"?
                if token == "-" { return None; }
                if token.len() > 1 && token.starts_with('0') { return None; }
                let idx: usize = token.parse().ok()?;
                cur = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

