impl Validator {
    pub fn new(root_schema: Value, base_uri: String, draft: Draft, assert_format: bool, registry: Registry) -> Self {
        Validator { draft, assert_format, registry, base_uri, root_schema }
    }

    pub fn validate_instance(&self, instance: &Value) -> (bool, Vec<ValidationError>) {
        let mut errors = Vec::new();
        let mut stack = Vec::new(); // for cycle detection: Vec<(schema_location, instance_json_ptr)>
        let valid = self.validate_at(&self.root_schema, instance, "", "", &self.base_uri, "", &mut errors, &mut stack);
        // Sort errors? Original order is not sorted, but evaluation order. Our validate_at pushes in evaluation order. Need to ensure order matches original's fixed order (type first, etc.).
        // For now, keep as is.
        (valid, errors)
    }

    fn validate_at(&self, schema: &Value, instance: &Value, instance_loc: &str, eval_path: &str, base_uri: &str, schema_ptr: &str, errors: &mut Vec<ValidationError>, stack: &mut Vec<(String, String)>) -> bool {
        // schema_ptr is JSON pointer from resource root to current schema (e.g., "", "/properties/foo", "/items", etc.)
        // base_uri is current base (without fragment), e.g., "file:///tmp/s.json" or $id
        // eval_path is evaluation path from root (e.g., "", "/properties/foo/type")
        // instance_loc is instance location (e.g., "", "/foo", "/0")
        // schema_location for current = base_uri + "#" + schema_ptr (with proper escaping? schema_ptr already escaped)
        // Handle boolean schemas
        if let Value::Bool(b) = schema {
            if *b {
                return true;
            } else {
                let msg = format!("False schema does not allow {}", json_str(instance));
                let schema_loc = format!("{}#{}", base_uri, schema_ptr);
                errors.push(ValidationError {
                    message: msg,
                    evaluation_path: eval_path.to_string(),
                    instance_location: instance_loc.to_string(),
                    schema_location: schema_loc,
                    keyword: "falseSchema".to_string(),
                });
                return false;
            }
        }
        let obj = match schema {
            Value::Object(m) => m,
            _ => {
                // Schema must be object or boolean; if not (e.g., number), it's invalid schema, but for instance validation, schema compilation would have already failed. However, if we encounter non-object/boolean subschema (e.g., {"type":123} where 123 is not a schema, but that's not a subschema, it's a keyword value. Subschemas are always objects/booleans. If someone has {"properties":{"foo":123}}, that's invalid schema (properties values must be schemas). Our schema validation should have caught it. For robustness, treat non-object subschema as valid? Or invalid? Let's treat as valid (ignore).
                return true;
            }
        };

        // Handle $ref (and $dynamicRef, $recursiveRef) with draft-specific sibling behavior
        // In drafts 4,6,7, if $ref present, ignore siblings (only $ref evaluated). In 2019,2020, evaluate both.
        let has_ref = obj.contains_key("$ref");
        let has_dynamic_ref = obj.contains_key("$dynamicRef") && self.draft == Draft::V2020;
        let has_recursive_ref = obj.contains_key("$recursiveRef") && self.draft == Draft::V2019;
        // Note: $recursiveRef in 2019? Our earlier test showed $recursiveRef ignored in all? Actually $recursiveRef "#" with default was valid (ignored). Hmm. Let's check: $recursiveRef should be evaluated in 2019. Our test with $recursiveRef "#" alone gave valid (since "#" refers to root which is {"$recursiveRef":"#"}? That's self-referential, cycle => valid? So it was evaluated but cycle => valid. Good. So $recursiveRef should be evaluated in 2019.
        // For simplicity, handle $ref, $dynamicRef (2020), $recursiveRef (2019)
        let mut ref_valid = true;
        let mut ref_errors_start = errors.len();
        // Check for $ref
        if has_ref {
            if let Some(ref_val) = obj.get("$ref") {
                if let Value::String(ref_str) = ref_val {
                    // Resolve ref
                    match self.resolve_ref(base_uri, schema_ptr, ref_str) {
                        Ok((target_schema, target_base, target_ptr, _anchor)) => {
                            // Cycle detection: check if (target_base+target_ptr, instance_loc) already in stack
                            let key = (format!("{}#{}", target_base, target_ptr), instance_loc.to_string());
                            if stack.contains(&key) {
                                // Cycle, treat as valid (to avoid infinite, as original does for pure alias cycles)
                                // Do nothing (valid)
                            } else {
                                stack.push(key.clone());
                                // Evaluation path for $ref: eval_path + "/$ref", but schema_location is target, not current? Original list shows evaluationPath "/$ref" with schemaLocation target (e.g., "#/$defs/foo"), not "#/$ref". Good.
                                // For nested errors, evaluationPath should be eval_path + "/$ref" + subpath? Original shows "/$ref/type" for nested. Good.
                                // So we need to validate target with eval_path + "/$ref", base=target_base, schema_ptr=target_ptr
                                let new_eval = if eval_path.is_empty() { "/$ref".to_string() } else { format!("{}/$ref", eval_path) };
                                // Note: instance_loc stays same
                                let valid = self.validate_at(&target_schema, instance, instance_loc, &new_eval, &target_base, &target_ptr, errors, stack);
                                stack.pop();
                                if !valid {
                                    ref_valid = false;
                                }
                            }
                        }
                        Err(_) => {
                            // Ref resolution failed? This should have been caught at schema compilation (schema invalid). For instance validation, if ref fails, treat as valid? Or invalid? Actually schema compilation would have failed, so we wouldn't be here. But for robustness, treat as valid (ignore).
                        }
                    }
                }
            }
            // In old drafts, if $ref present, ignore siblings (return ref_valid)
            if self.draft == Draft::V4 || self.draft == Draft::V6 || self.draft == Draft::V7 {
                return ref_valid;
            }
            // In new drafts, continue to evaluate siblings, but overall valid = ref_valid && siblings_valid
            // We'll evaluate siblings below and combine.
        }
        // Handle $dynamicRef (2020 only)
        if has_dynamic_ref {
            // Similar to $ref but with dynamic scope? Simplify: treat as $ref (resolve anchor, with dynamic lookup? For our purposes, resolve as normal anchor)
            if let Some(ref_val) = obj.get("$dynamicRef") {
                if let Value::String(ref_str) = ref_val {
                    match self.resolve_ref(base_uri, schema_ptr, ref_str) {
                        Ok((target_schema, target_base, target_ptr, _)) => {
                            let key = (format!("{}#{}", target_base, target_ptr), instance_loc.to_string());
                            if !stack.contains(&key) {
                                stack.push(key.clone());
                                let new_eval = if eval_path.is_empty() { "/$dynamicRef".to_string() } else { format!("{}/$dynamicRef", eval_path) };
                                let valid = self.validate_at(&target_schema, instance, instance_loc, &new_eval, &target_base, &target_ptr, errors, stack);
                                stack.pop();
                                if !valid { ref_valid = false; }
