                        }
                        Err(_) => {}
                    }
                }
            }
            // $dynamicRef does not ignore siblings (like $ref in new drafts)
        }
        if has_recursive_ref {
            if let Some(ref_val) = obj.get("$recursiveRef") {
                if let Value::String(ref_str) = ref_val {
                    // $recursiveRef "#" means? Resolve with recursive anchor logic? Simplify as normal $ref
                    match self.resolve_ref(base_uri, schema_ptr, ref_str) {
                        Ok((target_schema, target_base, target_ptr, _)) => {
                            let key = (format!("{}#{}", target_base, target_ptr), instance_loc.to_string());
                            if !stack.contains(&key) {
                                stack.push(key.clone());
                                let new_eval = if eval_path.is_empty() { "/$recursiveRef".to_string() } else { format!("{}/$recursiveRef", eval_path) };
                                let valid = self.validate_at(&target_schema, instance, instance_loc, &new_eval, &target_base, &target_ptr, errors, stack);
                                stack.pop();
                                if !valid { ref_valid = false; }
                            }
                        }
                        Err(_) => {}
                    }
                }
            }
        }

        // If old draft with $ref, already returned. For new drafts, need to remember ref_valid and combine with siblings.
        // Evaluate siblings (all other keywords)
        let siblings_valid = self.validate_siblings(obj, instance, instance_loc, eval_path, base_uri, schema_ptr, errors, stack);
        // Overall: ref_valid && siblings_valid (if has_ref in new drafts, else just siblings)
        if has_ref || has_dynamic_ref || has_recursive_ref {
            ref_valid && siblings_valid
        } else {
            siblings_valid
        }
    }

