                if let Value::Number(n) = v {
                    let max = n.as_u64().unwrap_or(usize::MAX as u64) as usize;
                    let len = s.chars().count();
                    if len > max {
                        let word = if max == 1 { "character" } else { "characters" };
                        let msg = format!("{} is longer than {} {}", json_str(instance), max, word);
                        self.push_error(errors, &msg, eval_path, "/maxLength", instance_loc, base_uri, schema_ptr, "maxLength");
                        valid = false;
                    }
                }
            }
            if let Some(v) = obj.get("pattern") {
                if let Value::String(pat) = v {
                    // Use fancy-regex, unanchored search (pattern is not implicitly anchored, must search, not match entire)
                    match fancy_regex::Regex::new(pat) {
                        Ok(re) => {
                            match re.is_match(s) {
                                Ok(true) => {},
                                _ => {
                                    // Note: pattern in message is raw (not JSON-escaped), with quotes around? Format: "\"xxx\" does not match \"pattern\"" where pattern is raw? Actually message is format!("{} does not match \"{}\"", json_str(instance), pat) where pat is raw string (may contain quotes, newlines, etc., not escaped). Good.
                                    let msg = format!("{} does not match \"{}\"", json_str(instance), pat);
                                    self.push_error(errors, &msg, eval_path, "/pattern", instance_loc, base_uri, schema_ptr, "pattern");
                                    valid = false;
                                }
                            }
                        }
                        Err(_) => {
                            // Invalid regex should have been caught at schema compilation (schema invalid). For instance validation, if schema invalid, we wouldn't be here. But if pattern invalid and schema compilation didn't catch (e.g., due to draft ignoring pattern? No, pattern always validated). For robustness, ignore.
                        }
                    }
                }
            }
        }
        // 6. Array: minItems, maxItems, uniqueItems
        if let Value::Array(arr) = instance {
            if let Some(v) = obj.get("minItems") {
                if let Value::Number(n) = v {
                    let min = n.as_u64().unwrap_or(0) as usize;
                    if arr.len() < min {
                        let word = if min == 1 { "item" } else { "items" };
                        let msg = format!("{} has less than {} {}", json_str(instance), min, word);
                        self.push_error(errors, &msg, eval_path, "/minItems", instance_loc, base_uri, schema_ptr, "minItems");
                        valid = false;
                    }
                }
            }
            if let Some(v) = obj.get("maxItems") {
                if let Value::Number(n) = v {
                    let max = n.as_u64().unwrap_or(usize::MAX as u64) as usize;
                    if arr.len() > max {
                        let word = if max == 1 { "item" } else { "items" };
                        let msg = format!("{} has more than {} {}", json_str(instance), max, word);
                        self.push_error(errors, &msg, eval_path, "/maxItems", instance_loc, base_uri, schema_ptr, "maxItems");
                        valid = false;
                    }
                }
            }
            if let Some(v) = obj.get("uniqueItems") {
                if *v == Value::Bool(true) {
                    let mut unique = true;
                    for i in 0..arr.len() {
                        for j in (i+1)..arr.len() {
                            if values_equal(&arr[i], &arr[j]) {
                                unique = false;
                                break;
                            }
                        }
                        if !unique { break; }
                    }
                    if !unique {
                        let msg = format!("{} has non-unique elements", json_str(instance));
                        self.push_error(errors, &msg, eval_path, "/uniqueItems", instance_loc, base_uri, schema_ptr, "uniqueItems");
                        valid = false;
                    }
                }
            }
        }
        // 7. Object: minProperties, maxProperties
        if let Value::Object(map) = instance {
            if let Some(v) = obj.get("minProperties") {
                if let Value::Number(n) = v {
                    let min = n.as_u64().unwrap_or(0) as usize;
                    if map.len() < min {
                        let word = if min == 1 { "property" } else { "properties" };
                        let msg = format!("{} has less than {} {}", json_str(instance), min, word);
                        self.push_error(errors, &msg, eval_path, "/minProperties", instance_loc, base_uri, schema_ptr, "minProperties");
                        valid = false;
                    }
                }
            }
            if let Some(v) = obj.get("maxProperties") {
                if let Value::Number(n) = v {
                    let max = n.as_u64().unwrap_or(usize::MAX as u64) as usize;
                    if map.len() > max {
                        let word = if max == 1 { "property" } else { "properties" };
                        let msg = format!("{} has more than {} {}", json_str(instance), max, word);
                        self.push_error(errors, &msg, eval_path, "/maxProperties", instance_loc, base_uri, schema_ptr, "maxProperties");
                        valid = false;
                    }
                }
            }
        }

        // Check for special case: properties + additionalProperties:false without patternProperties
        let is_special = obj.contains_key("properties") && obj.get("additionalProperties") == Some(&Value::Bool(false)) && !obj.contains_key("patternProperties");
        // In special case, required is evaluated after properties/additional (instead of before). We'll handle required position accordingly.
        // Also, what about dependentRequired? In special case, where? Not tested. Assume same as required (after)? Or before? Let's assume after as well? Actually in non-special, dependentRequired is after required, before properties. In special, maybe both after? We'll put both after for special.

        // 8. required, dependentRequired (before properties in normal, after in special)
        // To implement ordering, we'll evaluate required/dependentRequired either before or after properties depending on special.
        // For now, collect required errors but push in order? Simpler: If not special, evaluate required now; if special, defer until after properties/additional.
        let mut deferred_required_valid = true;
        let mut deferred_required_errors: Vec<ValidationError> = Vec::new();
        if !is_special {
            if !self.validate_required(obj, instance, instance_loc, eval_path, base_uri, schema_ptr, errors) {
                valid = false;
            }
            if !self.validate_dependent_required(obj, instance, instance_loc, eval_path, base_uri, schema_ptr, errors) {
                valid = false;
            }
        } else {
            // Defer: validate into temp, store for later
            let mut tmp = Vec::new();
            let r1 = self.validate_required(obj, instance, instance_loc, eval_path, base_uri, schema_ptr, &mut tmp);
            let r2 = self.validate_dependent_required(obj, instance, instance_loc, eval_path, base_uri, schema_ptr, &mut tmp);
            deferred_required_valid = r1 && r2;
            deferred_required_errors = tmp;
            // Don't push yet, don't set valid yet (will do after)
        }

        // 9. properties, patternProperties, additionalProperties, propertyNames, etc.
        // properties
        let mut evaluated_props: HashSet<String> = HashSet::new();
        if let Value::Object(inst_map) = instance {
            if let Some(props) = obj.get("properties") {
                if let Value::Object(prop_map) = props {
                    for (prop_name, prop_schema) in prop_map {
                        if let Some(prop_value) = inst_map.get(prop_name) {
                            evaluated_props.insert(prop_name.clone());
                            let new_instance_loc = format!("{}/{}", instance_loc, escape_pointer(prop_name));
                            let new_eval = format!("{}/properties/{}", eval_path, escape_pointer(prop_name));
                            let new_schema_ptr = format!("{}/properties/{}", schema_ptr, escape_pointer(prop_name));
                            // Need to handle $id in subschema? Subschema may have $id that changes base? For simplicity, check if prop_schema has $id/$anchor? Actually $id changes base for nested refs. We should update base_uri if subschema has $id.
                            let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(prop_schema, base_uri, &new_schema_ptr);
                            // For cycle? No need for properties (not $ref)
                            let prop_valid = self.validate_at(prop_schema, prop_value, &new_instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                            if !prop_valid {
                                valid = false;
                            }
                        }
                    }
                }
            }
            // patternProperties
            // Collect patterns that match each property? For each instance prop, for each pattern that matches, validate and mark as evaluated (for additionalProperties/unevaluated?).
            // For additionalProperties, a property is evaluated if it matches properties or patternProperties (for 2020, additionalProperties only applies to non-evaluated? Actually additionalProperties applies to properties not covered by properties/patternProperties. Good.)
            // For unevaluatedProperties, need to track all evaluated (including from allOf, etc.? That's complex (needs to track evaluated across applicators). Simplify: For unevaluated, only consider properties/patternProperties/additional? Actually unevaluatedProperties should consider all in-place applicators (properties, patternProperties, additionalProperties, allOf, anyOf, oneOf, if/then/else, etc.). That's complex. For now, implement simplified: unevaluatedProperties considers only properties/patternProperties (like additional)? But original handles full? For our test with {"properties":{"a":{}},"unevaluatedProperties":false} and {"a":1,"b":2}, unevaluated is "b" (since "a" evaluated via properties). Good, matches simplified. For more complex with allOf, need full. We'll implement basic and hope.
            let mut pattern_evaluated: HashSet<String> = HashSet::new();
            if let Some(pat_props) = obj.get("patternProperties") {
                if let Value::Object(pat_map) = pat_props {
                    // Pre-compile patterns? For each pattern, try to compile (if invalid, schema invalid, but we already validated, so assume valid)
                    for (pat_str, pat_schema) in pat_map {
                        let re = match fancy_regex::Regex::new(pat_str) {
                            Ok(r) => r,
                            Err(_) => continue, // invalid, ignore (should have been schema invalid)
                        };
                        for (inst_prop, inst_val) in inst_map.iter() {
                            let matched = match re.is_match(inst_prop) {
                                Ok(b) => b,
                                Err(_) => false,
                            };
                            if matched {
                                pattern_evaluated.insert(inst_prop.clone());
                                evaluated_props.insert(inst_prop.clone());
                                let new_instance_loc = format!("{}/{}", instance_loc, escape_pointer(inst_prop));
                                let new_eval = format!("{}/patternProperties/{}", eval_path, escape_pointer(pat_str));
                                // Schema ptr for patternProperties: need to escape pattern? Pattern may contain / and ~, need escaping for pointer? Yes, escape.
                                let new_schema_ptr = format!("{}/patternProperties/{}", schema_ptr, escape_pointer(pat_str));
                                let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(pat_schema, base_uri, &new_schema_ptr);
                                let prop_valid = self.validate_at(pat_schema, inst_val, &new_instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                                if !prop_valid {
                                    valid = false;
                                }
                            }
                        }
                    }
                }
            }
            // additionalProperties
            if let Some(additional) = obj.get("additionalProperties") {
                // Find unevaluated props (not in evaluated_props)
                let mut additional_props: Vec<String> = Vec::new();
                for k in inst_map.keys() {
                    if !evaluated_props.contains(k) {
                        additional_props.push(k.clone());
                    }
                }
                additional_props.sort(); // sorted for deterministic order and message?
                if additional == &Value::Bool(false) {
                    if !additional_props.is_empty() {
                        // Special handling: If no properties/pattern (i.e., evaluated_props empty because no properties/pattern defined?), then error is per-value "False schema..." for first only? Earlier we saw additional false without properties gives single "False schema..." for first value, not "Additional properties..." message.
                        // When does it give which?
                        // - With properties (or pattern?) defined, even if additional_props are those not covered, message is "Additional properties are not allowed ('x' was unexpected)" with all names.
                        // - Without properties and without patternProperties (i.e., additionalProperties alone), message is "False schema does not allow <value>" for first value only (single error).
                        // What about with patternProperties but without properties? Earlier pattern+additional without properties gave "Additional properties..." (with all). So if either properties or patternProperties present, use "Additional..." message. If neither, use "False schema..." for first.
                        let has_props = obj.contains_key("properties");
                        let has_pat = obj.contains_key("patternProperties");
                        if has_props || has_pat {
                            // Use Additional message with all names
                            let msg = if additional_props.len() == 1 {
                                format!("Additional properties are not allowed ('{}' was unexpected)", additional_props[0])
                            } else {
                                let quoted: Vec<String> = additional_props.iter().map(|s| format!("'{}'", s)).collect();
                                format!("Additional properties are not allowed ({} were unexpected)", quoted.join(", "))
                            };
                            self.push_error(errors, &msg, eval_path, "/additionalProperties", instance_loc, base_uri, schema_ptr, "additionalProperties");
                            valid = false;
                        } else {
                            // No properties/pattern, report first value only as False schema
                            // Which value first? Sorted? Additional_props sorted, first is smallest. For {"c":123,"d":456}, sorted ["c","d"], first "c" value 123. Original gave "False schema does not allow 123" (first). Good.
                            if let Some(first_prop) = additional_props.first() {
                                if let Some(first_val) = inst_map.get(first_prop) {
                                    let msg = format!("False schema does not allow {}", json_str(first_val));
                                    self.push_error(errors, &msg, eval_path, "/additionalProperties", instance_loc, base_uri, schema_ptr, "falseSchema");
                                    valid = false;
                                }
                            }
                        }
                    }
                } else if additional == &Value::Bool(true) {
                    // Always valid, no-op, mark all as evaluated? For unevaluated, additional true means all evaluated? Actually unevaluatedProperties after additionalProperties true? If additional true, all additional are valid, but are they considered evaluated for unevaluated? In 2020, unevaluatedProperties considers properties evaluated by all applicators, including additionalProperties? If additionalProperties is true, it evaluates all remaining, so unevaluated should pass. We'll mark all as evaluated.
                    for p in &additional_props {
                        evaluated_props.insert(p.clone());
                    }
                } else {
                    // Schema (object/boolean)
                    // For each additional prop, validate against additional schema
                    for prop_name in &additional_props {
                        if let Some(prop_val) = inst_map.get(prop_name) {
                            evaluated_props.insert(prop_name.clone());
                            let new_instance_loc = format!("{}/{}", instance_loc, escape_pointer(prop_name));
                            let new_eval = format!("{}/additionalProperties", eval_path);
                            let new_schema_ptr = format!("{}/additionalProperties", schema_ptr);
                            let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(additional, base_uri, &new_schema_ptr);
                            let prop_valid = self.validate_at(additional, prop_val, &new_instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                            if !prop_valid {
                                valid = false;
                            }
                        }
                    }
                }
            }
            // propertyNames (draft 6+)
            if self.draft != Draft::V4 {
                if let Some(pn_schema) = obj.get("propertyNames") {
                    // Special: if pn_schema is false (boolean false), error is single "False schema does not allow <whole object>" (not per-name). Earlier we saw that.
                    if pn_schema == &Value::Bool(false) {
                        if !inst_map.is_empty() {
                            let msg = format!("False schema does not allow {}", json_str(instance));
                            self.push_error(errors, &msg, eval_path, "/propertyNames", instance_loc, base_uri, schema_ptr, "propertyNames");
                            valid = false;
                        }
                    } else {
                        // For each property name, validate name string against pn_schema
                        // Collect names sorted? inst_map is BTreeMap (sorted), so iteration sorted. Good.
                        for prop_name in inst_map.keys() {
                            let name_val = Value::String(prop_name.clone());
                            // Instance location for propertyNames? Original list shows? For propertyNames with maxLength, errors are at instanceLocation ""? Or "/prop"? Let's check: Earlier propertyNames list? We didn't check list for propertyNames. For text, errors show name string, not location. For list, what instanceLocation? Probably "" (since propertyNames applies to object, not to property value)? Or "/prop"? Need to test.
                            // For now, use instance_loc (object location) for errors? Or new loc? Let's use instance_loc.
                            let new_eval = format!("{}/propertyNames", eval_path);
                            let new_schema_ptr = format!("{}/propertyNames", schema_ptr);
                            let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(pn_schema, base_uri, &new_schema_ptr);
                            // Validate name string
                            // Need to capture errors for name? Our validate_at will push errors with instance_loc = instance_loc (object)? But message should show name string, not object. Our validate_at for type etc. will format instance as name string (since we pass name_val as instance). Good. But instance_location should be? For propertyNames, instanceLocation in list is probably "" (object) or "/prop"? Let's assume "" (same as object).
                            let mut tmp_errors = Vec::new();
                            let pn_valid = self.validate_at(pn_schema, &name_val, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, &mut tmp_errors, stack);
                            if !pn_valid {
                                // Append tmp_errors to main errors (they already have messages with name string)
                                errors.extend(tmp_errors);
                                valid = false;
                            }
                        }
                    }
                }
            }
        } else {
            // Instance not object, propertyNames etc. ignored? But what about additionalProperties with non-object? Ignored (valid). Good.
            // However, need to handle dependencies/dependentRequired etc. which only apply if instance is object? Actually dependencies only if instance is object and contains trigger? If instance not object, ignore.
        }

        // If special, now push deferred required errors (after properties/additional)
        if is_special {
            if !deferred_required_valid {
                valid = false;
            }
            errors.extend(deferred_required_errors);
        }

        // dependencies / dependentRequired / dependentSchemas
        // dependencies: supported in all drafts? In 2019+, dependencies still works (as alias)? We'll support in all.
        // dependentRequired/Schemas: only 2019+
        if let Value::Object(inst_map) = instance {
            // dependencies
            if let Some(deps) = obj.get("dependencies") {
                if let Value::Object(dep_map) = deps {
                    // Sort keys? dep_map is BTreeMap (sorted). Good. Original order for dependencies? For multiple triggers, order sorted? Likely.
                    for (prop, dep_val) in dep_map {
                        if inst_map.contains_key(prop) {
                            match dep_val {
                                Value::Array(arr) => {
                                    // Required-like: each element must be string (property name), must exist
                                    for req in arr {
                                        if let Value::String(req_str) = req {
                                            if !inst_map.contains_key(req_str) {
                                                let msg = format!("\"{}\" is a required property", req_str);
                                                // Evaluation path? For dependencies with array, path is /dependencies/<prop>? Original list? Need to check. For now, use /dependencies
                                                self.push_error(errors, &msg, eval_path, "/dependencies", instance_loc, base_uri, schema_ptr, "dependencies");
                                                valid = false;
                                            }
                                        }
                                    }
                                }
                                _ => {
                                    // Schema (object/boolean): validate whole instance against dep schema
                                    let new_eval = format!("{}/dependencies/{}", eval_path, escape_pointer(prop));
                                    let new_schema_ptr = format!("{}/dependencies/{}", schema_ptr, escape_pointer(prop));
                                    let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(dep_val, base_uri, &new_schema_ptr);
                                    let dep_valid = self.validate_at(dep_val, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                                    if !dep_valid {
                                        valid = false;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            // dependentRequired (2019+)
            if self.draft == Draft::V2019 || self.draft == Draft::V2020 {
                if let Some(dep_req) = obj.get("dependentRequired") {
                    if let Value::Object(dep_map) = dep_req {
                        for (prop, req_val) in dep_map {
                            if inst_map.contains_key(prop) {
                                if let Value::Array(arr) = req_val {
                                    for req in arr {
                                        if let Value::String(req_str) = req {
                                            if !inst_map.contains_key(req_str) {
                                                let msg = format!("\"{}\" is a required property", req_str);
                                                self.push_error(errors, &msg, eval_path, "/dependentRequired", instance_loc, base_uri, schema_ptr, "dependentRequired");
                                                valid = false;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                // dependentSchemas (2019+)
                if let Some(dep_sch) = obj.get("dependentSchemas") {
                    if let Value::Object(dep_map) = dep_sch {
                        for (prop, sch) in dep_map {
                            if inst_map.contains_key(prop) {
                                let new_eval = format!("{}/dependentSchemas/{}", eval_path, escape_pointer(prop));
                                let new_schema_ptr = format!("{}/dependentSchemas/{}", schema_ptr, escape_pointer(prop));
                                let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(sch, base_uri, &new_schema_ptr);
                                let dep_valid = self.validate_at(sch, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                                if !dep_valid {
                                    valid = false;
                                }
                            }
                        }
                    }
                }
            }
        }

RS
"}

