// Core JSON Schema validator
use serde_json::{Value, Number};
use std::collections::{HashMap, HashSet};
use crate::numbers::*;
use crate::format::is_valid_format;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Draft {
    V4,
    V6,
    V7,
    V2019,
    V2020,
}

impl Draft {
    pub fn from_str(s: &str) -> Option<Draft> {
        match s {
            "4" => Some(Draft::V4),
            "6" => Some(Draft::V6),
            "7" => Some(Draft::V7),
            "2019" => Some(Draft::V2019),
            "2020" => Some(Draft::V2020),
            _ => None,
        }
    }
    pub fn from_schema_url(url: &str) -> Option<Draft> {
        // Normalize: strip trailing '#'? Both with and without are known.
        // Check exact matches for 20 known URLs
        match url {
            "http://json-schema.org/draft-04/schema" | "http://json-schema.org/draft-04/schema#"
            | "https://json-schema.org/draft-04/schema" | "https://json-schema.org/draft-04/schema#" => Some(Draft::V4),
            "http://json-schema.org/draft-06/schema" | "http://json-schema.org/draft-06/schema#"
            | "https://json-schema.org/draft-06/schema" | "https://json-schema.org/draft-06/schema#" => Some(Draft::V6),
            "http://json-schema.org/draft-07/schema" | "http://json-schema.org/draft-07/schema#"
            | "https://json-schema.org/draft-07/schema" | "https://json-schema.org/draft-07/schema#" => Some(Draft::V7),
            "https://json-schema.org/draft/2019-09/schema" | "https://json-schema.org/draft/2019-09/schema#"
            | "http://json-schema.org/draft/2019-09/schema" | "http://json-schema.org/draft/2019-09/schema#" => Some(Draft::V2019),
            "https://json-schema.org/draft/2020-12/schema" | "https://json-schema.org/draft/2020-12/schema#"
            | "http://json-schema.org/draft/2020-12/schema" | "http://json-schema.org/draft/2020-12/schema#" => Some(Draft::V2020),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct ValidationError {
    pub message: String,
    pub evaluation_path: String,
    pub instance_location: String,
    pub schema_location: String,
    pub keyword: String,
}

#[derive(Debug, Clone)]
pub struct Detail {
    pub evaluation_path: String,
    pub instance_location: String,
    pub schema_location: String,
    pub valid: bool,
    pub errors: Option<Value>, // object mapping keyword -> message or array?
    pub annotations: Option<Value>,
    pub dropped_annotations: Option<Value>,
    pub details: Option<Vec<Detail>>, // for hierarchical
}

// Registry for $ref
#[derive(Debug, Clone)]
pub struct RegistryEntry {
    pub value: Value,
    pub base_uri: String, // e.g., "file:///tmp/s.json" without fragment
    pub draft: Draft,
}

pub struct Registry {
    pub resources: HashMap<String, RegistryEntry>, // key: URI without fragment (e.g., "file:///tmp/s.json", "https://example.com/schema")
    pub anchors: HashMap<String, String>, // key: "base_uri#anchor" -> pointer? Or "base_uri#anchor" -> target URI+pointer? Simplify: map from anchor URI (e.g., "file:///tmp/s.json#myanchor") to (resource_uri, pointer)
    pub anchor_targets: HashMap<String, (String, String)>, // anchor URI -> (resource_uri, json_pointer)
}

impl Registry {
    pub fn new() -> Self {
        Registry { resources: HashMap::new(), anchors: HashMap::new(), anchor_targets: HashMap::new() }
    }
}

// Helper to escape JSON pointer token
pub fn escape_pointer(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}
pub fn unescape_pointer(s: &str) -> String {
