pub fn json_pointer_get<'a>(value: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() { return Some(value); }
    if !pointer.starts_with('/') { return None; }
    let mut cur = value;
    for token in pointer[1..].split('/') {
        let token = unescape_pointer(token);
        match cur {
            Value::Object(map) => {
                cur = map.get(&token)?;
            }
            Value::Array(arr) => {
                // token must be index (no leading zeros? "01" invalid? JSON pointer for arrays: index must be 0 or [1-9][0-9]*, no leading zeros, and "-" is invalid for retrieval? For our purposes, parse as usize, reject leading zeros and "-"?
                if token == "-" { return None; }
                if token.len() > 1 && token.starts_with('0') { return None; }
                let idx: usize = token.parse().ok()?;
                cur = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

