                                format!("Unevaluated properties are not allowed ({} were unexpected)", quoted.join(", "))
                            };
                            self.push_error(errors, &msg, eval_path, "/unevaluatedProperties", instance_loc, base_uri, schema_ptr, "unevaluatedProperties");
                            valid = false;
                        } else if uneval == &Value::Bool(true) {
                        } else {
                            for prop_name in &unevaluated_props {
                                if let Some(prop_val) = inst_map.get(prop_name) {
                                    let new_instance_loc = format!("{}/{}", instance_loc, escape_pointer(prop_name));
                                    let new_eval = format!("{}/unevaluatedProperties", eval_path);
                                    let new_schema_ptr = format!("{}/unevaluatedProperties", schema_ptr);
                                    let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(uneval, base_uri, &new_schema_ptr);
                                    let prop_valid = self.validate_at(uneval, prop_val, &new_instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                                    if !prop_valid {
                                        valid = false;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Combinators: allOf, anyOf, oneOf, not
        if let Some(allof) = obj.get("allOf") {
            if let Value::Array(arr) = allof {
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let new_eval = format!("{}/allOf/{}", eval_path, idx);
                    let new_schema_ptr = format!("{}/allOf/{}", schema_ptr, idx);
                    let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(sub_schema, base_uri, &new_schema_ptr);
                    let sub_valid = self.validate_at(sub_schema, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                    if !sub_valid {
                        valid = false;
                    }
                }
            }
        }
        if let Some(anyof) = obj.get("anyOf") {
            if let Value::Array(arr) = anyof {
                let mut any_valid = false;
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let mut tmp = Vec::new();
                    let mut tmp_stack = stack.clone();
                    let new_eval = format!("{}/anyOf/{}", eval_path, idx);
                    let new_schema_ptr = format!("{}/anyOf/{}", schema_ptr, idx);
                    let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(sub_schema, base_uri, &new_schema_ptr);
                    if self.validate_at(sub_schema, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, &mut tmp, &mut tmp_stack) {
                        any_valid = true;
                        break;
                    }
                }
                if !any_valid {
                    let msg = format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", json_str(instance));
                    self.push_error(errors, &msg, eval_path, "/anyOf", instance_loc, base_uri, schema_ptr, "anyOf");
                    valid = false;
                }
            }
        }
        if let Some(oneof) = obj.get("oneOf") {
            if let Value::Array(arr) = oneof {
                let mut valid_count = 0;
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let mut tmp = Vec::new();
                    let mut tmp_stack = stack.clone();
                    let new_eval = format!("{}/oneOf/{}", eval_path, idx);
                    let new_schema_ptr = format!("{}/oneOf/{}", schema_ptr, idx);
                    let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(sub_schema, base_uri, &new_schema_ptr);
                    if self.validate_at(sub_schema, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, &mut tmp, &mut tmp_stack) {
                        valid_count += 1;
                    }
                }
                if valid_count == 0 {
                    let msg = format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", json_str(instance));
                    self.push_error(errors, &msg, eval_path, "/oneOf", instance_loc, base_uri, schema_ptr, "oneOf");
                    valid = false;
                } else if valid_count > 1 {
                    let msg = format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", json_str(instance));
                    self.push_error(errors, &msg, eval_path, "/oneOf", instance_loc, base_uri, schema_ptr, "oneOf");
                    valid = false;
                }
            }
        }
        if let Some(not_schema) = obj.get("not") {
            let mut tmp = Vec::new();
            let mut tmp_stack = stack.clone();
            let new_eval = format!("{}/not", eval_path);
            let new_schema_ptr = format!("{}/not", schema_ptr);
            let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(not_schema, base_uri, &new_schema_ptr);
            if self.validate_at(not_schema, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, &mut tmp, &mut tmp_stack) {
                // not schema passed, so outer fails
                let msg = format!("{} is not allowed for {}", json_str(not_schema), json_str(instance));
                self.push_error(errors, &msg, eval_path, "/not", instance_loc, base_uri, schema_ptr, "not");
                valid = false;
            }
        }

        // if/then/else (draft 7+)
        if self.draft == Draft::V7 || self.draft == Draft::V2019 || self.draft == Draft::V2020 {
            if let Some(if_schema) = obj.get("if") {
                let mut tmp = Vec::new();
                let mut tmp_stack = stack.clone();
                let new_eval_if = format!("{}/if", eval_path);
                let new_schema_ptr_if = format!("{}/if", schema_ptr);
                let (new_base_if, new_schema_ptr_adj_if) = self.resolve_subschema_base(if_schema, base_uri, &new_schema_ptr_if);
                let if_valid = self.validate_at(if_schema, instance, instance_loc, &new_eval_if, &new_base_if, &new_schema_ptr_adj_if, &mut tmp, &mut tmp_stack);
                if if_valid {
                    if let Some(then_schema) = obj.get("then") {
                        let new_eval = format!("{}/then", eval_path);
                        let new_schema_ptr = format!("{}/then", schema_ptr);
                        let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(then_schema, base_uri, &new_schema_ptr);
                        let then_valid = self.validate_at(then_schema, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                        if !then_valid {
                            valid = false;
                        }
                    }
                } else {
                    if let Some(else_schema) = obj.get("else") {
                        let new_eval = format!("{}/else", eval_path);
                        let new_schema_ptr = format!("{}/else", schema_ptr);
                        let (new_base, new_schema_ptr_adj) = self.resolve_subschema_base(else_schema, base_uri, &new_schema_ptr);
                        let else_valid = self.validate_at(else_schema, instance, instance_loc, &new_eval, &new_base, &new_schema_ptr_adj, errors, stack);
                        if !else_valid {
                            valid = false;
                        }
                    }
                }
            } else {
                // if without then/else? Actually then/else without if are ignored? Spec says then/else only apply if if present. So ignore.
            }
        }

        // format (only if assert_format and instance is string)
        if self.assert_format {
            if let Value::String(s) = instance {
                if let Some(fmt) = obj.get("format") {
                    if let Value::String(fmt_str) = fmt {
                        if !is_valid_format(fmt_str, s) {
                            let msg = format!("{} is not a \"{}\"", json_str(instance), fmt_str);
                            self.push_error(errors, &msg, eval_path, "/format", instance_loc, base_uri, schema_ptr, "format");
                            valid = false;
                        }
                    }
                }
            }
        }

        valid
    }

    fn validate_type(&self, type_val: &Value, instance: &Value, instance_loc: &str, eval_path: &str, base_uri: &str, schema_ptr: &str, errors: &mut Vec<ValidationError>) -> bool {
        let mut types: Vec<String> = Vec::new();
        match type_val {
            Value::String(s) => types.push(s.clone()),
            Value::Array(arr) => {
                for v in arr {
                    if let Value::String(s) = v {
                        types.push(s.clone());
                    }
                }
            }
            _ => return true, // invalid schema, ignore (should have been caught)
        }
        for t in &types {
            if check_type(t, instance) {
                return true;
            }
        }
        // Failed
        let msg = if types.len() == 1 {
            format!("{} is not of type \"{}\"", json_str(instance), types[0])
        } else {
            // Sort types alphabetically? Original sorts: ["string","null"] input gave "null", "string" sorted. Good.
            let mut sorted = types.clone();
            sorted.sort();
            let quoted: Vec<String> = sorted.iter().map(|s| format!("\"{}\"", s)).collect();
            format!("{} is not of types {}", json_str(instance), quoted.join(", "))
        };
        self.push_error(errors, &msg, eval_path, "/type", instance_loc, base_uri, schema_ptr, "type");
        false
    }

    fn validate_required(&self, obj: &serde_json::Map<String, Value>, instance: &Value, instance_loc: &str, eval_path: &str, base_uri: &str, schema_ptr: &str, errors: &mut Vec<ValidationError>) -> bool {
        if let Value::Object(map) = instance {
            if let Some(req) = obj.get("required") {
                if let Value::Array(arr) = req {
                    let mut valid = true;
                    for v in arr {
                        if let Value::String(prop) = v {
                            if !map.contains_key(prop) {
                                let msg = format!("\"{}\" is a required property", prop);
                                self.push_error(errors, &msg, eval_path, "/required", instance_loc, base_uri, schema_ptr, "required");
                                valid = false;
                            }
                        }
                    }
                    return valid;
                }
            }
        }
        true
    }

    fn validate_dependent_required(&self, obj: &serde_json::Map<String, Value>, instance: &Value, instance_loc: &str, eval_path: &str, base_uri: &str, schema_ptr: &str, errors: &mut Vec<ValidationError>) -> bool {
        // dependentRequired only in 2019+? In earlier drafts, ignore? Our earlier test showed dependentRequired ignored in 4,6,7. Good.
        if self.draft != Draft::V2019 && self.draft != Draft::V2020 {
            return true;
        }
        if let Value::Object(map) = instance {
            if let Some(dep) = obj.get("dependentRequired") {
                if let Value::Object(dep_map) = dep {
                    let mut valid = true;
                    for (prop, req_val) in dep_map {
                        if map.contains_key(prop) {
                            if let Value::Array(arr) = req_val {
                                for v in arr {
                                    if let Value::String(req_str) = v {
                                        if !map.contains_key(req_str) {
                                            let msg = format!("\"{}\" is a required property", req_str);
                                            self.push_error(errors, &msg, eval_path, "/dependentRequired", instance_loc, base_uri, schema_ptr, "dependentRequired");
                                            valid = false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    return valid;
                }
            }
        }
        true
    }

    fn push_error(&self, errors: &mut Vec<ValidationError>, message: &str, eval_path: &str, keyword_path: &str, instance_loc: &str, base_uri: &str, schema_ptr: &str, keyword: &str) {
        let full_eval = format!("{}{}", eval_path, keyword_path);
        // Schema location: base_uri + "#" + schema_ptr + keyword_path (with proper? keyword_path already starts with /)
        // For root, schema_ptr is "", so schema_loc = base + "#/keyword"? For nested, base + "#/properties/foo/type"? Good.
        // Need to handle base_uri that may already contain fragment? Base_uri is without fragment (we strip). Good.
        let full_schema_ptr = format!("{}{}", schema_ptr, keyword_path);
        let schema_loc = format!("{}#{}", base_uri, full_schema_ptr);
        errors.push(ValidationError {
            message: message.to_string(),
            evaluation_path: full_eval,
            instance_location: instance_loc.to_string(),
            schema_location: schema_loc,
            keyword: keyword.to_string(),
        });
    }

    fn resolve_subschema_base(&self, subschema: &Value, current_base: &str, schema_ptr: &str) -> (String, String) {
        // Check if subschema has $id (or id for V4) that changes base
        // $id must be string, valid URI-reference, no fragment (except trailing #)? If present, new base is resolved against current base? Actually $id is resolved against current base to get absolute? Example: current base file:///tmp/s.json, subschema $id "http://example.com/foo" (absolute) => new base http://example.com/foo. If $id "other.json" (relative) => resolved to file:///tmp/other.json? Need to handle.
        // For simplicity, if $id present and is string, resolve via Url::parse(current_base)?.join($id)? Then strip fragment? Actually $id should not have fragment (except #). We'll strip trailing #? Or split at # and take first part as base?
        // Return (new_base_without_fragment, new_schema_ptr_for_new_base? Actually schema_ptr for new base should be ""? Since new base is a new resource, its pointer resets? For schemaLocation generation, subschema with $id should have location new_base + "#" (for itself) and nested paths relative to new base? Our current schema_ptr is old_base-relative (e.g., "/properties/foo"). For new base, the subschema itself is at "" (root of new resource), not "/properties/foo". But our evaluation_path should still be old path? EvaluationPath is from root, not base-relative. SchemaLocation should be new_base + fragment relative to new resource.
        // Simplify: If subschema has $id, new_base = resolved $id (without fragment), new_schema_ptr = "" (since it's root of new resource). For nested validation inside it, schema_ptr will extend from "".
        // If no $id, return (current_base, schema_ptr) unchanged.
        if let Value::Object(map) = subschema {
            let id_key = if self.draft == Draft::V4 { "id" } else { "$id" };
            if let Some(id_val) = map.get(id_key) {
                if let Value::String(id_str) = id_val {
                    // Resolve against current base
                    // Current base is like "file:///tmp/s.json" (without #). To resolve, need base with trailing? Use Url::parse(current_base + "#")? Actually base without fragment, join should work: Url::parse("file:///tmp/s.json")?.join("other.json") => file:///tmp/other.json. Good. For absolute $id, join returns absolute.
                    // For $id "", empty? Then base stays? Empty $id means same base? Original: $id "" is valid and ignored (base stays file://...). Good. So if id_str empty, return current.
                    if id_str.is_empty() {
                        return (current_base.to_string(), schema_ptr.to_string());
                    }
                    // Try to resolve
                    if let Ok(base_url) = url::Url::parse(current_base) {
                        if let Ok(resolved) = base_url.join(id_str) {
                            // Strip fragment? $id should not have fragment except #? If it has #foo (invalid, but schema validation would have failed), we still handle: take without fragment?
                            let mut new_base = resolved.to_string();
                            // Remove trailing #? Url::to_string for "https://example.com/schema" (no #) gives "https://example.com/schema" (no #). For "https://example.com/schema#" gives with #? Actually Url preserves #? For "https://example.com/schema#", to_string gives "https://example.com/schema#"? Possibly. We want base without fragment (without #). So split at # and take first part.
                            if let Some(hash_pos) = new_base.find('#') {
                                new_base = new_base[..hash_pos].to_string();
                            }
                            // If new_base ends with #? Already stripped. Good.
                            return (new_base, "".to_string());
                        }
                    }
                    // If resolve fails (invalid URI), ignore (return current)? Schema validation would have failed for invalid $id, but for instance validation we wouldn't be here if schema invalid. So ignore.
                }
            }
        }
        (current_base.to_string(), schema_ptr.to_string())
    }

    fn resolve_ref(&self, base_uri: &str, _schema_ptr: &str, ref_str: &str) -> Result<(Value, String, String, bool), String> {
        // Resolve $ref string against base_uri to absolute URI + fragment, then look up in registry.
        // Returns (target_schema_value, target_base_without_fragment, target_pointer, is_anchor?)
        // base_uri is without fragment, e.g., "file:///tmp/s.json"
        // ref_str can be "#", "#/foo", "#anchor", "other.json", "other.json#/foo", "http://...", etc.
        // Use Url to resolve
        let base_url = url::Url::parse(base_uri).map_err(|_| "parse base".to_string())?;
        let resolved = base_url.join(ref_str).map_err(|_| "resolve".to_string())?;
        let resolved_str = resolved.to_string();
        // Split into base (without fragment) and fragment (after #)
        let (target_base, fragment) = if let Some(hash_pos) = resolved_str.find('#') {
            let (b, f) = resolved_str.split_at(hash_pos);
            (b.to_string(), f[1..].to_string()) // f without #
        } else {
            (resolved_str.clone(), "".to_string())
        };
        // Fragment may be URL-encoded? Need to decode? For JSON pointer, fragment is URL-encoded (e.g., spaces %20, / as %2F? Actually JSON pointer in URI fragment must be UTF-8 encoded? The fragment for "#/a~1b" is "/a~1b" (with / not encoded? In URI fragment, / is allowed, no need to encode. For spaces, %20. For our purposes, fragment from Url::to_string() will be percent-encoded? Example: ref "#/a b" (with space) => resolved fragment "a%20b"? Need to decode? Use percent_encoding? Or url crate's fragment() which decodes? Let's use resolved.fragment() which returns decoded? Actually Url::fragment() returns Option<&str> with percent-decoding? No, it returns raw? Let's check docs: fragment() returns the fragment without #, percent-decoded? Hmm. Simpler: Use resolved.fragment().unwrap_or("") and then percent-decode? For JSON pointer, need to decode %XX.
        // For now, use fragment as is, but percent-decode?
        let frag_decoded = percent_decode(&fragment);
        // Look up target_base in registry
        // If target_base == base_uri (same resource) or empty? For "#", target_base == base_uri (since join("#") gives base + "#", split gives base). Good.
        // If target_base empty? For ref like "#foo" with base file://..., resolved is file://...#foo, base is file://..., good. For ref ""? Not possible ($ref "" is valid? It refers to current resource root? "#" vs ""? $ref "" means current base without fragment? That would be base itself? Probably same as "#". We'll handle.
        let mut lookup_base = target_base.clone();
        if lookup_base.is_empty() {
            lookup_base = base_uri.to_string();
        }
        // If lookup_base not in registry, it means the resource hasn't been fetched? But our registry should have been pre-populated with all file/http resources via recursive fetching at schema load time. If not found, return error (should have been fetched, but if missing, it's an error that should have been schema invalid at load time).
        // For anchors: fragment may be anchor name (without /) or JSON pointer (starting with / or empty)
        if frag_decoded.is_empty() {
            // Refers to whole resource (e.g., "#", "other.json", "other.json#")
            if let Some(entry) = self.registry.resources.get(&lookup_base) {
                return Ok((entry.value.clone(), lookup_base.clone(), "".to_string(), false));
            } else {
                return Err("not found".to_string());
            }
        } else if frag_decoded.starts_with('/') {
            // JSON pointer
            if let Some(entry) = self.registry.resources.get(&lookup_base) {
                // Resolve pointer within resource value
                // Fragment may contain URL-encoded chars? Already decoded. Good.
                // JSON pointer must be valid (escape ~, etc.)
                if let Some(target) = json_pointer_get(&entry.value, &frag_decoded) {
                    // Target base stays same, pointer is frag_decoded
                    // But what if target subschema has $id that changes base? For schemaLocation, should use new base? Actually if pointer target has $id, its base is new. Our validate_at will handle $id via resolve_subschema_base when it encounters it? But for $ref target, we need to return the correct base for validation (which may be different if target has $id or is inside a subschema with $id?). Simplify: Return lookup_base as base, and pointer as is. The validate_at will handle $id inside target when it traverses? Actually validate_at's base_uri param is the base for the target schema itself. If target schema has $id, its base should be new. But our resolve_subschema_base is called for subschemas during validation, not for $ref target itself. For $ref target, if it has $id, we should update base now? Or let validate_at handle? validate_at checks $id only for subschemas, not for itself? Actually validate_at's base_uri is passed in, and it doesn't check its own $id, only children's. For $ref target, if target itself has $id, its base should be new. We should check here.
                    // Check if target has $id
                    let (new_base, new_ptr) = if let Value::Object(map) = target {
                        let id_key = if self.draft == Draft::V4 { "id" } else { "$id" };
                        if let Some(Value::String(id_str)) = map.get(id_key) {
                            if !id_str.is_empty() {
                                if let Ok(burl) = url::Url::parse(&lookup_base) {
                                    if let Ok(res) = burl.join(id_str) {
                                        let mut nb = res.to_string();
                                        if let Some(p) = nb.find('#') { nb = nb[..p].to_string(); }
                                        // New pointer is "" (root of new resource)
                                        (nb, "".to_string())
                                    } else { (lookup_base.clone(), frag_decoded.clone()) }
                                } else { (lookup_base.clone(), frag_decoded.clone()) }
                            } else { (lookup_base.clone(), frag_decoded.clone()) }
                        } else { (lookup_base.clone(), frag_decoded.clone()) }
                    } else { (lookup_base.clone(), frag_decoded.clone()) };
                    // If new_base != lookup_base, need to return new_base and ""? But what about pointer? If target has $id, its location is new_base#"", not old_base#/pointer. Good.
                    // However, what if target is inside a subschema with $id (not itself, but ancestor)? Then its base is already new (since registry resources are per $id?). Our registry should have collected $id resources separately, with their own base. The pointer frag_decoded is relative to the resource root (lookup_base), which may contain nested $ids. To get correct base for target, we'd need to walk from resource root to target, tracking $id changes. That's complex. For simplicity, ignore nested $id for $ref targets (assume no nested $id, or use lookup_base).
                    // For common cases (no nested $id), this is fine.
                    return Ok((target.clone(), new_base, new_ptr, false));
                } else {
                    return Err("pointer not found".to_string());
                }
            } else {
                return Err("not found".to_string());
            }
        } else {
            // Plain anchor (e.g., "myanchor", "foo")
            // Look up anchor: key is lookup_base + "#" + frag_decoded
            let anchor_uri = format!("{}#{}", lookup_base, frag_decoded);
            if let Some((res_uri, ptr)) = self.registry.anchor_targets.get(&anchor_uri) {
                if let Some(entry) = self.registry.resources.get(res_uri) {
                    // Resolve pointer within that resource
                    let target = if ptr.is_empty() {
                        &entry.value
                    } else {
                        json_pointer_get(&entry.value, ptr).ok_or("anchor pointer".to_string())?
                    };
                    // Base for anchor target? Should be res_uri (without fragment)? Or anchor's base? For $anchor, base stays same resource? Actually anchor is within same resource, base doesn't change (unless $id). So return res_uri as base, ptr as pointer.
                    // But what about $id inside? Ignore for now.
                    return Ok((target.clone(), res_uri.clone(), ptr.clone(), true));
                } else {
                    return Err("anchor resource not found".to_string());
                }
            } else {
                // Also try without base? For draft4 id anchors? The anchor may be defined with id "#myanchor" in same resource? Our collect should have registered it as base#myanchor. Good.
                // If not found, return error (anchor does not exist) – This will be reported as schema invalid at load time with "Anchor '...' does not exist". For instance validation, if anchor missing, schema compilation would have failed, so we wouldn't be here. Return error.
                return Err(format!("anchor {} not found", frag_decoded));
            }
        }
    }
}

fn percent_decode(s: &str) -> String {
    // Decode %XX sequences
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '%' {
            let h1 = chars.next();
            let h2 = chars.next();
            if let (Some(a), Some(b)) = (h1, h2) {
                if let (Some(v1), Some(v2)) = (a.to_digit(16), b.to_digit(16)) {
                    let byte = (v1 * 16 + v2) as u8;
                    out.push(byte as char);
                } else {
                    out.push('%');
                    out.push(a);
                    out.push(b);
                }
            } else {
                out.push('%');
                if let Some(a) = h1 { out.push(a); }
                if let Some(b) = h2 { out.push(b); }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn json_str(v: &Value) -> String {
    v.to_string()
}

fn format_enum_list(arr: &[Value]) -> String {
    if arr.is_empty() {
        return "".to_string();
    } else if arr.len() == 1 {
        return json_str(&arr[0]);
    } else if arr.len() == 2 {
        return format!("{} or {}", json_str(&arr[0]), json_str(&arr[1]));
    } else if arr.len() == 3 {
        return format!("{}, {} or {}", json_str(&arr[0]), json_str(&arr[1]), json_str(&arr[2]));
    } else {
        let others = arr.len() - 2;
        return format!("{}, {} or {} other candidates", json_str(&arr[0]), json_str(&arr[1]), others);
