fn percent_decode(s: &str) -> String {
    // Decode %XX sequences
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '%' {
            let h1 = chars.next();
            let h2 = chars.next();
            if let (Some(a), Some(b)) = (h1, h2) {
                if let (Some(v1), Some(v2)) = (a.to_digit(16), b.to_digit(16)) {
                    let byte = (v1 * 16 + v2) as u8;
                    out.push(byte as char);
                } else {
                    out.push('%');
                    out.push(a);
                    out.push(b);
                }
            } else {
                out.push('%');
                if let Some(a) = h1 { out.push(a); }
                if let Some(b) = h2 { out.push(b); }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn json_str(v: &Value) -> String {
    v.to_string()
}

fn format_enum_list(arr: &[Value]) -> String {
    if arr.is_empty() {
        return "".to_string();
    } else if arr.len() == 1 {
        return json_str(&arr[0]);
    } else if arr.len() == 2 {
        return format!("{} or {}", json_str(&arr[0]), json_str(&arr[1]));
    } else if arr.len() == 3 {
        return format!("{}, {} or {}", json_str(&arr[0]), json_str(&arr[1]), json_str(&arr[2]));
    } else {
        let others = arr.len() - 2;
        return format!("{}, {} or {} other candidates", json_str(&arr[0]), json_str(&arr[1]), others);
        // Note: For 4, others=2 => "1, 2 or 2 other candidates" (matches original). For 5, "1, 2 or 3 other candidates". Good. What about singular? For 3, we handle separately (no "candidates"). For >3, others>=2, always plural "candidates" (even if others==1? But len>3 => others>=2? For len=4, others=2, plural. Good. So never singular.
    }
}

fn check_type(t: &str, instance: &Value) -> bool {
    match t {
        "string" => matches!(instance, Value::String(_)),
        "integer" => {
            if let Value::Number(n) = instance {
                is_integer_number(n)
            } else { false }
        }
        "number" => matches!(instance, Value::Number(_)),
        "boolean" => matches!(instance, Value::Bool(_)),
        "null" => matches!(instance, Value::Null),
        "array" => matches!(instance, Value::Array(_)),
        "object" => matches!(instance, Value::Object(_)),
        _ => false,
    }
}
