fn resolve_ref_url(base_uri: &str, ref_str: &str) -> Result<(String, String), String> {
    // Resolve ref_str against base_uri to (abs_base_without_fragment, fragment_decoded)
    // Use Url::join
    let base_url = url::Url::parse(base_uri).map_err(|e| format!("Invalid base {}", e))?;
    let resolved = base_url.join(ref_str).map_err(|e| format!("Invalid ref {}", e))?;
    let full = resolved.to_string();
    // Split at #
    if let Some(pos) = full.find('#') {
        let base = full[..pos].to_string();
        let frag_encoded = &full[pos+1..];
