    }
}

fn percent_decode(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '%' {
            let h1 = chars.next();
            let h2 = chars.next();
            if let (Some(a), Some(b)) = (h1, h2) {
                if let (Some(v1), Some(v2)) = (a.to_digit(16), b.to_digit(16)) {
                    out.push((v1*16+v2) as u8 as char);
                } else {
                    out.push('%'); out.push(a); out.push(b);
                }
            } else {
                out.push('%');
                if let Some(a) = h1 { out.push(a); }
                if let Some(b) = h2 { out.push(b); }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn file_url_to_path(url_str: &str) -> Result<std::path::PathBuf, String> {
    match url::Url::parse(url_str) {
        Ok(u) => {
            match u.to_file_path() {
                Ok(p) => Ok(p),
                Err(_) => {
                    // Fallback for "file:foo" (relative)
                    let path_part = u.path();
                    Ok(std::path::PathBuf::from(path_part))
                }
            }
        }
        Err(e) => Err(e.to_string()),
    }
}

